package oepul.o6_12

# Gemeinsame Hilfsdefinitionen für die Maßnahme 12 "Insektizidverzicht Wein, Obst und Hopfen".

params := data.o6_12.measure_parameters

year := input.farm.year

parcels := object.get(input, ["land", "parcels"], [])

o612 := object.get(input, ["oepul", "o6_12"], {})

participating_measures := {m | some m in object.get(input, ["oepul", "participating_measures"], [])}

participates if o612.participating == true

measure_crop_categories := {c | some c in params.eligible_crop_categories}

eligible_land_use_codes := {c | some c in params.eligible_land_use_codes}

ineligible_usage_types := {t.usage_type | some t in data.o6_12.ineligible_usage_types}

usage_type(p) := object.get(p, ["crop", "usage_type"], "regular")

parcel_codes(p) := {c | some c in object.get(p, "oepul_codes", [])}

crop_category(p) := object.get(p, ["crop", "crop_category"], "other")

# Wein-, Obst- und Hopfenflächen des Betriebes (Geltungsbereich des Insektizidverzichts).
# Schnittweingärten zählen zur Weinfläche, Reb- und Baumschulen nicht.
is_wine_fruit_hop_parcel(p) if {
	crop_category(p) in measure_crop_categories
	not usage_type(p) in {"rebschule", "baumschule"}
}

# Flächen, die für die Mindestteilnahmefläche angerechnet werden.
counts_for_minimum_area(p) if {
	is_wine_fruit_hop_parcel(p)
	not usage_type(p) in ineligible_usage_types
	object.get(p, "country", "AT") == "AT"
}

listed_fruit_crops(yr) := {f.crop_name | some f in data.o6_12.fruit_crops; f.valid_from_year <= yr}

contract_period := cp if {
	some cp in data.o6_12.contract_periods
	cp.start_year == o612.contract_start_year
}

contract_end_year := to_number(substring(params.contract_end_date, 0, 4))

# Vertragszeitraum läuft im betrachteten Jahr.
year_in_contract_period if {
	contract_period
	o612.contract_start_year <= year
	year <= contract_end_year
}

date_ns(d) := time.parse_ns("2006-01-02", d)

date_on_or_before(a, b) if date_ns(a) <= date_ns(b)

exit_obj := object.get(o612, "exit", {})

exit_requested if exit_obj.requested == true

has_vineyard if {
	some p in parcels
	crop_category(p) == "vineyard"
	not usage_type(p) in {"rebschule"}
}

package oepul.o6_12

# Vertragszeitraum, Ausstieg, Maßnahmenwechsel, Flächenänderungen, Übernahme, höhere Gewalt
# und Sonderregelungen 2026.

rebzikade := data.o6_12.rebzikade_2026

# --- Rückzahlungsfreier Ausstieg wegen Amerikanischer Rebzikade (Hinweis 12.06.2026) --

rebzikade_exit_conditions_unmet contains "exit_not_requested" if not exit_requested

rebzikade_exit_conditions_unmet contains "reason_not_rebzikade" if {
	exit_requested
	exit_obj.reason != "rebzikade_2026"
}

rebzikade_exit_conditions_unmet contains "before_application_year_2026" if {
	exit_requested
	to_number(substring(exit_obj.request_date, 0, 4)) < rebzikade.exit_available_from_application_year
}

rebzikade_exit_conditions_unmet contains "farm_has_no_vineyard" if {
	exit_requested
	not has_vineyard
}

rebzikade_exit_conditions_unmet contains "not_submitted_via_force_majeure_form" if {
	exit_requested
	not exit_obj.submitted_via_force_majeure_form == true
}

rebzikade_exit_conditions_unmet contains "control_reason_not_stated" if {
	exit_requested
	not exit_obj.rebzikade_reason_stated == true
}

rebzikade_exit_conditions_unmet contains "not_approved" if {
	exit_requested
	exit_obj.approved == false
}

rebzikade_exit_without_repayment if {
	participates
	count(rebzikade_exit_conditions_unmet) == 0
}

rebzikade_exit_year := to_number(substring(exit_obj.request_date, 0, 4)) if rebzikade_exit_without_repayment

# Ende des ursprünglichen Vertragszeitraums mit Beginn der einzelbetrieblichen Meldung.
contract_end_date := exit_obj.request_date if rebzikade_exit_without_repayment

else := params.contract_end_date

# --- Regulärer Ausstieg (Allg. TNB 6, 7.1; SRL 1.7.2) --------------------------

bio_switch := object.get(o612, "switch_to_bio", {})

bio_switch_without_repayment if {
	bio_switch.requested == true
	date_on_or_before(bio_switch.application_date, data.o6_12.measure_switches[0].latest_contract_change)
}

# Abmeldung während des Jahres: Maßnahme im betroffenen Förderjahr nicht mehr gültig.
exit_in_current_year if {
	exit_requested
	to_number(substring(exit_obj.request_date, 0, 4)) == year
}

# Ausstieg ist bis zur Ankündigung/Durchführung einer Vor-Ort-Kontrolle bzw. Mitteilung einer Verwaltungskontrolle möglich.
exit_timely if {
	exit_requested
	not o612.control_announced_date
}

exit_timely if {
	exit_requested
	date_ns(exit_obj.request_date) < date_ns(o612.control_announced_date)
}

regular_exit_before_contract_end if {
	exit_requested
	not rebzikade_exit_without_repayment
	date_ns(exit_obj.request_date) < date_ns(params.contract_end_date)
	not bio_switch_without_repayment
}

# Rückforderung der bisher gewährten Maßnahmenprämien bis Vertragsbeginn.
repayment_required_reasons contains "exit_before_contract_end" if regular_exit_before_contract_end

repayment_required_reasons contains "payment_application_missing_over_one_year" if {
	participates
	o612.payment_application_missing_over_one_year == true
}

repayment_required_reasons contains "excluded_after_second_full_reduction" if excluded_from_measure

repayment_required_reasons contains "control_refused" if {
	participates
	o612.control_refused == true
}

# Nach Ausstieg, Ausschluss oder einjähriger Nichtabgabe: Wiedereinstieg nur mit neuem Maßnahmenantrag;
# bei Maßnahme 12 war der letzte Einstieg mit Förderjahr 2025 möglich.
reentry_possible if {
	new_entry_possible_for_contract_start(year + 1)
}

# --- Jährlicher Zahlungsantrag (SRL 1.10.5.3) ----------------------------------

annual_payment_application_missing if {
	participates
	year > o612.contract_start_year
	o612.annual_application_submitted == false
}

# Verpflichtung bleibt aufrecht, für das Jahr erfolgt keine Zahlung.
commitment_continues_without_payment if {
	annual_payment_application_missing
	not o612.payment_application_missing_over_one_year == true
}

# --- Flächenänderungen (SRL 1.7.2.3 - 1.7.2.5) --------------------------------

tolerance := data.o6_12.area_reduction_tolerance

area_reduction_tolerance_ha(previous_ha) := max([min([tolerance.max_share_of_previous_year_area * previous_ha, tolerance.max_ha_per_year]), tolerance.always_allowed_ha_per_year])

area_reduction_ha := max([o612.previous_year_area_ha - eligible_area_ha, 0])

general_area_reduction_within_tolerance if {
	area_reduction_ha <= area_reduction_tolerance_ha(o612.previous_year_area_ha)
}

# Bei Maßnahme 12 sind die Flächen an die jährlich verfügbaren Wein-, Obst- und Hopfenflächen gebunden.
area_reduction_repayment_required if {
	not params.premium_area_bound_annually
	o612.area_reduction_cause != "loss_of_control"
	not general_area_reduction_within_tolerance
}

area_variation_permitted if params.premium_area_bound_annually

# Flächenzugänge unterliegen bei Maßnahme 12 keiner Prämienbeschränkung.
area_additions_fully_eligible if not params.subject_to_area_addition_limit

# --- Maßnahmenübernahme (SRL 1.7.3.1, Allg. TNB 6.3) ---------------------------

takeover := object.get(o612, "takeover", {})

takeover_deadline(yr) := sprintf("%d-%s", [yr, data.o6_12.takeover_rules.deadline_month_day_special_years]) if {
	yr in {y | some y in data.o6_12.takeover_rules.special_years}
}

takeover_deadline(yr) := sprintf("%d-%s", [yr, data.o6_12.takeover_rules.deadline_month_day]) if {
	not yr in {y | some y in data.o6_12.takeover_rules.special_years}
}

takeover_issues contains "submitted_after_deadline" if {
	takeover.is_takeover == true
	not date_on_or_before(takeover.submission_date, takeover_deadline(year))
}

takeover_issues contains "extension_exceeds_50_percent" if {
	takeover.is_takeover == true
	takeover.additional_area_ha > data.o6_12.takeover_rules.max_extension_share_of_taken_over_area * takeover.taken_over_area_ha
}

takeover_issues contains "taker_already_participating" if {
	takeover.is_takeover == true
	takeover.taker_previously_participating == true
}

takeover_issues contains "not_approved_by_ama" if {
	takeover.is_takeover == true
	takeover.approved_by_ama == false
}

takeover_valid if {
	takeover.is_takeover == true
	count(takeover_issues) == 0
}

# --- Betriebsübertragung (SRL 1.7.2.2, § 14 Abs. 2 GSP-AV) ----------------------

farm_transfer := object.get(o612, "farm_transfer", {})

farm_transfer_issues contains "commitment_not_continued" if {
	farm_transfer.occurred == true
	farm_transfer.successor_continues_commitment == false
}

farm_transfer_issues contains "notification_later_than_4_weeks" if {
	farm_transfer.occurred == true
	date_ns(farm_transfer.notification_date) > time.add_date(date_ns(farm_transfer.effective_date), 0, 0, 28)
}

# --- Höhere Gewalt (§ 6 GSP-AV, SRL 1.7.4.1) ------------------------------------

force_majeure := object.get(o612, "force_majeure", {})

force_majeure_case_recognised if {
	some c in data.o6_12.force_majeure_cases
	c.case_id == force_majeure.case_id
}

force_majeure_claim_timely if {
	date_ns(force_majeure.claim_date) <= time.add_date(date_ns(force_majeure.able_to_notify_date), 0, 0, 7 * data.o6_12.force_majeure_rules.notification_weeks)
}

force_majeure_premium_retained if {
	force_majeure_case_recognised
	force_majeure_claim_timely
	force_majeure.documented == true
}

# Behördlich angeordnete Bekämpfung von Pflanzenkrankheiten gilt als höhere Gewalt (§ 6 Abs. 1 Z 5 GSP-AV).
official_disease_order_is_force_majeure if force_majeure.case_id == "official_disease_order"

# --- Dauerhafte / vorübergehende Umstände (SRL 1.7.4.2, 1.7.4.3) ------------------

circumstance := object.get(o612, "circumstance", {})

circumstance_no_repayment if {
	circumstance.type in {"permanent", "temporary"}
	circumstance.beyond_control == true
	circumstance.notified == true
}

permanent_circumstance_premium_in_event_year if {
	circumstance.type == "permanent"
	circumstance_no_repayment
	date_ns(circumstance.event_date) > date_ns(sprintf("%s-04-15", [substring(circumstance.event_date, 0, 4)]))
}

permanent_circumstance_premium_in_event_year if {
	circumstance.type == "permanent"
	circumstance_no_repayment
	force_majeure_premium_retained
}

temporary_circumstance_premium_in_year if {
	circumstance.type == "temporary"
	circumstance_no_repayment
	circumstance.conditions_met_on_changed_areas == true
}

temporary_circumstance_premium_in_year if {
	circumstance.type == "temporary"
	circumstance_no_repayment
	force_majeure_premium_retained
}

# --- Revisionsklausel (SRL 1.7.5) ----------------------------------------------

revision_clause_exit_without_repayment if o612.contract_adjustment_refused == true

# --- Aufbewahrung (§ 16 GSP-AV) -------------------------------------------------

records_retention_until := sprintf("%d-12-31", [to_number(substring(contract_end_date, 0, 4)) + 4])

# --- Dürre 2026: automatische Anerkennung Ernteverpflichtung nur für Ackerkulturen --

drought_district_listed(state, district) if {
	some d in data.o6_12.drought_2026_harvest_districts
	d.federal_state == state
	d.district in {"*", district}
}

drought_2026_automatic_harvest_exemption(p) if {
	year == 2026
	p.land_use_code == "A"
	drought_district_listed(input.farm.region.federal_state, input.farm.region.district)
}

# Für Wein-, Obst- und Hopfenflächen der Maßnahme 12 greift die automatische Anerkennung nicht;
# eine nicht erfüllte Ernteverpflichtung erfordert ein einzelbetriebliches Ansuchen.
individual_force_majeure_claim_needed contains p.parcel_id if {
	participates
	some p in parcels
	is_wine_fruit_hop_parcel(p)
	object.get(p, ["minimum_management", "harvested"], true) == false
	not drought_2026_automatic_harvest_exemption(p)
}

package oepul.o6_12

# Zugangs- und Fördervoraussetzungen, Förderfähigkeit der Flächen, Kombinationen.

# --- Förderwerbende Person (SRL 1.4, Allg. TNB 5.2) ---------------------------

applicant := object.get(input, ["farm", "applicant"], {})

applicant_type_rule := r if {
	some r in data.o6_12.applicant_types
	r.legal_form == applicant.legal_form
}

applicant_ineligibility_reasons contains "public_body_not_eligible_for_measure_12" if {
	applicant.legal_form == "public_body"
}

applicant_ineligibility_reasons contains "public_body_share_exceeds_25_percent" if {
	applicant_type_rule.max_public_body_share_percent != null
	object.get(applicant, "public_body_share_percent", 0) > applicant_type_rule.max_public_body_share_percent
}

applicant_ineligibility_reasons contains "not_active_farmer" if {
	applicant.is_active_farmer == false
}

applicant_ineligibility_reasons contains "not_farming_in_own_name_and_account" if {
	applicant.farms_in_own_name_and_account == false
}

applicant_ineligibility_reasons contains "unknown_legal_form" if {
	applicant.legal_form
	not applicant_type_rule
}

applicant_eligible if {
	applicant.legal_form
	count(applicant_ineligibility_reasons) == 0
}

# --- Antragstellung und Einstieg (Merkblatt 5, SRL 1.10.5.2, § 33 GSP-AV) ------

application_deadline := contract_period.application_deadline

application_timely if {
	date_on_or_before(o612.application_submitted_date, application_deadline)
}

entry_year_allowed if o612.contract_start_year <= params.last_entry_year

new_entry_possible_for_contract_start(start_year) if {
	start_year <= params.last_entry_year
}

# --- Mindestteilnahmefläche (Merkblatt 3.2, SRL 2.12) --------------------------

wine_fruit_hop_area_ha := sum([p.area_ha | some p in parcels; counts_for_minimum_area(p)])

is_first_commitment_year if year == o612.contract_start_year

first_year_minimum_area_status := "met" if {
	is_first_commitment_year
	wine_fruit_hop_area_ha >= params.first_year_minimum_area_ha
} else := "not_met" if {
	is_first_commitment_year
} else := "met" if {
	o612.first_year_area_ha >= params.first_year_minimum_area_ha
} else := "not_met" if {
	o612.first_year_area_ha < params.first_year_minimum_area_ha
} else := "unknown"

# --- Betriebsmindestgröße im 1. ÖPUL-Teilnahmejahr (SRL 1.6.1) ---------------

min_size := data.o6_12.minimum_farm_size_first_year

is_first_oepul_year if year == object.get(input, ["oepul", "first_participation_year"], -1)

farm_minimum_size_met if not is_first_oepul_year

farm_minimum_size_met if {
	is_first_oepul_year
	object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= min_size.protected_cultivation_min_ha
}

farm_minimum_size_met if {
	is_first_oepul_year
	object.get(input, ["land", "total_area_ha"], 0) >= min_size.agricultural_area_min_ha
}

# --- Betriebliche Kombination mit Biologischer Wirtschaftsweise ----------------

bio_teilbetrieb := object.get(input, ["oepul", "bio_teilbetrieb"], {})

bio_teilbetrieb_arable_grassland if {
	bio_teilbetrieb.is_participating == true
	bio_teilbetrieb.organic_cultural_area == "arable_grassland"
}

bio_combination_conflict if {
	participates
	"1B" in participating_measures
	not bio_teilbetrieb_arable_grassland
}

# --- Zugangsvoraussetzungen gesamt (SRL 1.12.1.1) ------------------------------

access_condition_failures contains "applicant_not_eligible" if {
	participates
	not applicant_eligible
}

access_condition_failures contains "application_not_timely" if {
	participates
	not application_timely
}

access_condition_failures contains "entry_after_last_entry_year" if {
	participates
	not entry_year_allowed
}

access_condition_failures contains "first_year_minimum_area_not_met" if {
	participates
	first_year_minimum_area_status == "not_met"
}

access_condition_failures contains "farm_minimum_size_not_met" if {
	participates
	not farm_minimum_size_met
}

access_condition_failures contains "combination_with_organic_farming_excluded" if {
	bio_combination_conflict
}

# Bei Nichterfüllung im 1. Jahr kommt kein Vertrag zustande; ab dem 2. Jahr keine Prämie im betroffenen Jahr.
access_condition_consequence := "no_contract" if {
	count(access_condition_failures) > 0
	is_first_commitment_year
} else := "no_premium_in_year" if {
	count(access_condition_failures) > 0
} else := "none"

contract_established if {
	participates
	contract_period
	application_timely
	entry_year_allowed
	not access_condition_consequence == "no_contract"
}

# --- Förderfähigkeit der Einzelflächen ----------------------------------------

national_park_without_premium := {n.national_park | some n in data.o6_12.national_park_rules; n.o6_12_premium_possible == false}

parcel_exclusions[p.parcel_id] contains "not_wine_fruit_hop_area" if {
	some p in parcels
	not crop_category(p) in measure_crop_categories
}

parcel_exclusions[p.parcel_id] contains "ineligible_usage_type" if {
	some p in parcels
	usage_type(p) in ineligible_usage_types
}

parcel_exclusions[p.parcel_id] contains "land_use_code_not_permanent_crop" if {
	some p in parcels
	p.land_use_code
	not p.land_use_code in eligible_land_use_codes
}

parcel_exclusions[p.parcel_id] contains "vineyard_not_in_vineyard_register" if {
	some p in parcels
	crop_category(p) == "vineyard"
	p.in_vineyard_register == false
}

parcel_exclusions[p.parcel_id] contains "fruit_crop_not_listed" if {
	some p in parcels
	crop_category(p) == "orchard"
	not object.get(p, ["crop", "crop_name"], "") in listed_fruit_crops(year)
}

parcel_exclusions[p.parcel_id] contains "ungrafted_fruit_planting_material" if {
	some p in parcels
	crop_category(p) == "orchard"
	p.crop.grafted_planting_material == false
}

parcel_exclusions[p.parcel_id] contains "code_op" if {
	some p in parcels
	"OP" in parcel_codes(p)
}

parcel_exclusions[p.parcel_id] contains "code_vf_experimental_area" if {
	some p in parcels
	"VF" in parcel_codes(p)
}

parcel_exclusions[p.parcel_id] contains "measure_specific_op_code" if {
	some p in parcels
	"12" in object.get(p, "measure_op_exclusions", [])
}

parcel_exclusions[p.parcel_id] contains "not_declared_for_measure" if {
	some p in parcels
	not "12" in object.get(p, "declared_measures", [])
}

parcel_exclusions[p.parcel_id] contains "national_park_without_premium" if {
	some p in parcels
	object.get(p, "national_park", null) in national_park_without_premium
}

parcel_exclusions[p.parcel_id] contains "outside_austria" if {
	some p in parcels
	object.get(p, "country", "AT") != "AT"
}

parcel_exclusions[p.parcel_id] contains "gloez_landscape_element" if {
	some p in parcels
	p.is_gloez_landscape_element == true
}

parcel_exclusions[p.parcel_id] contains "not_mainly_agricultural_use" if {
	some p in parcels
	p.mainly_agricultural_use == false
}

parcel_exclusions[p.parcel_id] contains "non_agricultural_use_exceeds_14_days" if {
	some p in parcels
	object.get(p, "non_agricultural_use_days", 0) > 14
}

parcel_exclusions[p.parcel_id] contains "below_minimum_parcel_size_50_m2" if {
	some p in parcels
	p.area_ha * 10000 < 50
}

parcel_exclusions[p.parcel_id] contains "minimum_management_not_met" if {
	some p in parcels
	some k in ["properly_planted", "annual_care", "harvested"]
	object.get(p, ["minimum_management", k], true) == false
}

parcel_exclusions[p.parcel_id] contains "overlap_with_other_public_funding" if {
	some p in parcels
	p.other_public_funding_same_service == true
}

parcel_exclusions[p.parcel_id] contains "commitment_not_fulfilled_whole_year" if {
	some p in parcels
	p.commitment_fulfilled_whole_year == false
}

eligible_parcel_ids := {p.parcel_id |
	some p in parcels
	crop_category(p) in measure_crop_categories
	not parcel_exclusions[p.parcel_id]
}

eligible_area_ha := sum([p.area_ha | some p in parcels; p.parcel_id in eligible_parcel_ids])

# Obstflächen mit unveredeltem Pflanzgut sind mit dem Code OP zu beantragen.
op_code_required_parcels contains p.parcel_id if {
	some p in parcels
	crop_category(p) == "orchard"
	p.crop.grafted_planting_material == false
	not "OP" in parcel_codes(p)
}

# Ernteverpflichtung nicht erfüllt -> verpflichtende Vergabe des Codes OP.
op_code_required_parcels contains p.parcel_id if {
	some p in parcels
	is_wine_fruit_hop_parcel(p)
	object.get(p, ["minimum_management", "harvested"], true) == false
	not "OP" in parcel_codes(p)
	not "12" in object.get(p, "measure_op_exclusions", [])
}

# --- Kombination auf der Einzelfläche (Anhang L) ------------------------------

combination_cell(measure_id) := c if {
	some c in data.o6_12.combination_anhang_l.cells
	c.measure_id == measure_id
}

parcel_combination_conflicts[p.parcel_id] contains m if {
	some p in parcels
	p.parcel_id in eligible_parcel_ids
	some m in object.get(p, "declared_measures", [])
	m != "12"
	combination_cell(m).combinable_on_parcel == false
}

parcel_combination_landscape_element_only[p.parcel_id] contains m if {
	some p in parcels
	p.parcel_id in eligible_parcel_ids
	some m in object.get(p, "declared_measures", [])
	combination_cell(m).only_landscape_elements == true
}

# Optionaler Zuschlag "Einsatz von Organismen oder Pheromonen" (Maßnahme 10) wird bei Teilnahme an 12 um 50 % reduziert.
o6_10_organism_supplement_factor := 0.5 if participates

else := 1.0

package oepul.o6_12

# Prämienberechnung, Modulation, Obergrenzen, Auszahlung.

rate_for(category, yr) := r.eur_per_ha if {
	some r in data.o6_12.premium_rates
	r.crop_category == category
	r.year_from <= yr
	yr <= r.year_to
}

parcel_premium_eur[p.parcel_id] := p.area_ha * rate_for(crop_category(p), year) if {
	some p in parcels
	p.parcel_id in eligible_parcel_ids
}

gross_premium_eur := sum([a | some a in parcel_premium_eur])

# Gründe, aus denen im betrachteten Jahr keine Maßnahmenprämie gewährt wird.
premium_blocking_reasons contains "not_participating" if not participates

premium_blocking_reasons contains "no_valid_contract" if {
	participates
	not contract_established
}

premium_blocking_reasons contains "year_outside_contract_period" if {
	participates
	not year_in_contract_period
}

premium_blocking_reasons contains "access_conditions_not_met" if {
	participates
	access_condition_consequence != "none"
}

premium_blocking_reasons contains "rebzikade_exit_in_year" if {
	rebzikade_exit_year == year
}

premium_blocking_reasons contains "rebzikade_exit_in_previous_year" if {
	rebzikade_exit_year < year
}

premium_blocking_reasons contains "deregistered_in_year" if {
	exit_in_current_year
	not rebzikade_exit_without_repayment
}

premium_blocking_reasons contains "annual_payment_application_missing" if annual_payment_application_missing

premium_blocking_reasons contains "control_refused" if {
	participates
	o612.control_refused == true
}

premium_blocking_reasons contains "excluded_from_measure" if excluded_from_measure

premium_granted if count(premium_blocking_reasons) == 0

# --- Übererklärung (§ 42 Abs. 4, § 46 GSP-AV) ----------------------------------

sanction_rules := data.o6_12.sanction_rules

declared_area_ha := object.get(o612, "declared_area_ha", eligible_area_ha)

determined_area_ha := object.get(o612, "determined_area_ha", declared_area_ha)

overdeclaration_ha := max([declared_area_ha - determined_area_ha, 0])

overdeclaration_sanctioned if {
	overdeclaration_ha > 0
	overdeclaration_ha > (sanction_rules.overdeclaration_tolerance_percent / 100) * determined_area_ha
}

overdeclaration_sanctioned if {
	overdeclaration_ha > sanction_rules.overdeclaration_tolerance_ha
}

premium_basis_area_ha := max([determined_area_ha - (sanction_rules.overdeclaration_multiplier * overdeclaration_ha), 0]) if {
	overdeclaration_sanctioned
} else := min([declared_area_ha, determined_area_ha])

# Durchschnittlicher Prämiensatz der förderfähigen Flächen (für die flächenbasierte Kürzung).
average_rate_eur_per_ha := gross_premium_eur / eligible_area_ha if eligible_area_ha > 0

else := 0

premium_after_area_check_eur := premium_basis_area_ha * average_rate_eur_per_ha

# --- Modulation (SRL 1.9.2.2) ---------------------------------------------------

band_upper(b, total) := min([total, b.to_ha_inclusive]) if b.to_ha_inclusive != null

band_upper(b, total) := total if b.to_ha_inclusive == null

band_weight(b, total) := w if {
	portion := band_upper(b, total) - b.from_ha_exclusive
	portion > 0
	w := portion * b.payment_factor
}

band_weight(b, total) := 0 if band_upper(b, total) - b.from_ha_exclusive <= 0

modulation_factor(total) := 1 if total <= 0

modulation_factor(total) := f if {
	total > 0
	f := sum([band_weight(b, total) | some b in data.o6_12.modulation_bands]) / total
}

farm_modulation_factor := modulation_factor(object.get(input, ["land", "total_area_ha"], 0))

# --- Auszahlungsschätzung -------------------------------------------------------

payment_estimate_eur := 0 if not premium_granted

else := round(((premium_after_area_check_eur * (1 - (content_reduction_percent / 100))) * farm_modulation_factor) * 100) / 100

# Von der Gewährung kann abgesehen werden, wenn der Betrag 50 Euro nicht überschreitet.
payment_may_be_waived if {
	premium_granted
	payment_estimate_eur <= data.o6_12.payment_rules.minimum_payment_eur
}

advance_payment_max_eur := payment_estimate_eur * data.o6_12.payment_rules.advance_payment_max_share

payment_deadline := sprintf("%d-%s", [year + 1, data.o6_12.payment_rules.payment_deadline_month_day_following_year])

payments_not_before := sprintf("%d-%s", [year, data.o6_12.payment_rules.payments_not_before_month_day])

# --- Obergrenze für Flächenzahlungen je Schlag (SRL 1.9.2.1) -----------------------

general_area_cap_eur_per_ha := c.eur_per_ha if {
	some c in data.o6_12.area_payment_caps
	c.cap_id == "general"
	c.year_from <= year
	year <= c.year_to
}

parcel_cap_excess_eur_per_ha[p.parcel_id] := excess if {
	some p in parcels
	p.parcel_id in eligible_parcel_ids
	total := rate_for(crop_category(p), year) + object.get(p, "other_area_payments_eur_per_ha", 0)
	excess := total - general_area_cap_eur_per_ha
	excess > 0
}

# --- Zusammenfassung ------------------------------------------------------------

decision := {
	"measure": "o6_12",
	"year": year,
	"participates": participates,
	"contract_established": contract_established,
	"access_condition_failures": access_condition_failures,
	"eligible_parcel_ids": eligible_parcel_ids,
	"eligible_area_ha": eligible_area_ha,
	"gross_premium_eur": gross_premium_eur,
	"premium_blocking_reasons": premium_blocking_reasons,
	"obligation_breaches": obligation_breaches,
	"content_reduction_percent": content_reduction_percent,
	"modulation_factor": farm_modulation_factor,
	"payment_estimate_eur": payment_estimate_eur,
	"repayment_required_reasons": repayment_required_reasons,
}

